export const MIGRATIONS: { name: string; sql: string }[] = [
  { name: "001_init.sql", sql: "-- Kinpath schema v1.\n-- Every row carries clinic_id. Row-level security (RLS) walls clinics apart and enforces\n-- who can see each section of a patient's record. The app connects as kp_app, never as owner,\n-- so these policies always apply. The same rules live in @kinpath/core/permissions.ts and a\n-- test checks the two stay in sync.\n\nCREATE ROLE kp_app NOLOGIN;\n\n-- ---------- session identity (set per transaction by the app) ----------\nCREATE FUNCTION kp_user() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id', true), '')::uuid $$;\nCREATE FUNCTION kp_clinic() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.clinic_id', true), '') $$;\nCREATE FUNCTION kp_role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.role', true), '') $$;\n\n-- ---------- tables ----------\nCREATE TABLE clinics (\n  id text PRIMARY KEY,\n  name text NOT NULL,\n  timezone text NOT NULL DEFAULT 'America/New_York'\n);\n\nCREATE TABLE app_users (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  role text NOT NULL CHECK (role IN ('nurse','physician','financial_counselor','scheduler','clinic_admin','patient','partner')),\n  display_name text NOT NULL,\n  email text NOT NULL,\n  preferred_lang text NOT NULL DEFAULT 'en' CHECK (preferred_lang IN ('en','es')),\n  UNIQUE (clinic_id, email)\n);\n\nCREATE TABLE patients (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  user_id uuid NOT NULL REFERENCES app_users(id),\n  first_name text NOT NULL,\n  last_name text NOT NULL,\n  preferred_lang text NOT NULL DEFAULT 'en' CHECK (preferred_lang IN ('en','es')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE partner_grants (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  partner_user_id uuid NOT NULL REFERENCES app_users(id),\n  sections text[] NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  revoked_at timestamptz,\n  CHECK (sections <@ ARRAY['schedule','results','meds','money','record']::text[])  -- never 'messages'\n);\n\nCREATE TABLE cycles (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('ivf','egg_freezing','fet','iui')),\n  stage text NOT NULL,\n  stim_day int,\n  started_on date NOT NULL\n);\n\nCREATE TABLE med_orders (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  cycle_id uuid NOT NULL REFERENCES cycles(id),\n  medication text NOT NULL,\n  dose text NOT NULL,\n  time_of_day time NOT NULL\n);\n\nCREATE TABLE dose_logs (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  med_order_id uuid NOT NULL REFERENCES med_orders(id),\n  scheduled_for timestamptz NOT NULL,\n  taken_at timestamptz,\n  reported_missed_at timestamptz\n);\n\nCREATE TABLE clinic_ranges (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  analyte text NOT NULL,\n  unit text NOT NULL,\n  day_from int NOT NULL,\n  day_to int NOT NULL,\n  low numeric NOT NULL,\n  high numeric NOT NULL,\n  in_range_en text NOT NULL,\n  in_range_es text NOT NULL,\n  approved_by text NOT NULL,\n  CHECK (low <= high AND day_from <= day_to)\n);\n\nCREATE TABLE lab_results (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  analyte text NOT NULL,\n  unit text NOT NULL,\n  value numeric NOT NULL,\n  stim_day int NOT NULL,\n  collected_at timestamptz NOT NULL,\n  status text NOT NULL CHECK (status IN ('in_range','below_range','above_range','no_range','unit_mismatch')),\n  entered_by uuid NOT NULL REFERENCES app_users(id),\n  source text NOT NULL DEFAULT 'staff_entry' CHECK (source IN ('staff_entry','emr_feed','emr_partner','patient_upload'))\n);\n\nCREATE TABLE protocol_sections (\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  id text NOT NULL,\n  title text NOT NULL,\n  body_en text NOT NULL,\n  body_es text NOT NULL,\n  approved_by text NOT NULL,\n  PRIMARY KEY (clinic_id, id)\n);\n\nCREATE TABLE handoffs (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('missed_dose','question','urgent_symptom','result_review','crisis')),\n  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','drafted','sent','read','closed')),\n  patient_message text NOT NULL,\n  triage jsonb NOT NULL,\n  dose_log_id uuid REFERENCES dose_logs(id),\n  lab_result_id uuid REFERENCES lab_results(id),\n  draft text,\n  draft_source text,\n  sent_text text,\n  sent_by uuid REFERENCES app_users(id),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  sent_at timestamptz,\n  read_at timestamptz,\n  -- A draft can never exist for urgent or crisis messages. People call those patients.\n  CHECK (NOT (kind IN ('urgent_symptom','crisis') AND draft IS NOT NULL))\n);\n\nCREATE TABLE consents (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  form text NOT NULL,\n  signed_by uuid NOT NULL REFERENCES app_users(id),\n  signed_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE audit_events (\n  id bigserial PRIMARY KEY,\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  actor_user_id uuid NOT NULL,\n  action text NOT NULL,\n  patient_id uuid,\n  detail jsonb NOT NULL DEFAULT '{}'::jsonb,\n  at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ---------- access helpers ----------\n-- Staff section matrix. Must match STAFF_SECTIONS in packages/core/src/permissions.ts.\nCREATE FUNCTION kp_staff_sections(role text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$\n  SELECT CASE role\n    WHEN 'nurse' THEN ARRAY['schedule','results','meds','record','messages']\n    WHEN 'physician' THEN ARRAY['schedule','results','meds','record','messages']\n    WHEN 'financial_counselor' THEN ARRAY['schedule','money']\n    WHEN 'scheduler' THEN ARRAY['schedule']\n    ELSE ARRAY[]::text[] END\n$$;\n\n-- SECURITY DEFINER so it can read patients and grants regardless of the caller's own row access.\nCREATE FUNCTION kp_can_view(p_patient uuid, p_section text) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM patients p\n    WHERE p.id = p_patient AND p.clinic_id = kp_clinic()\n      AND (\n        (kp_role() = 'patient' AND p.user_id = kp_user())\n        OR (kp_role() = 'partner' AND p_section <> 'messages' AND EXISTS (\n              SELECT 1 FROM partner_grants g\n              WHERE g.patient_id = p.id AND g.partner_user_id = kp_user()\n                AND g.revoked_at IS NULL AND p_section = ANY (g.sections)))\n        OR (p_section = ANY (kp_staff_sections(kp_role())))\n      )\n  )\n$$;\n\nCREATE FUNCTION kp_is_patient_self(p_patient uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT kp_role() = 'patient' AND EXISTS (SELECT 1 FROM patients WHERE id = p_patient AND user_id = kp_user() AND clinic_id = kp_clinic())\n$$;\n\nCREATE FUNCTION kp_is_clinician() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT kp_role() IN ('nurse','physician') $$;\n\n-- ---------- row-level security ----------\nALTER TABLE clinics ENABLE ROW LEVEL SECURITY;\nALTER TABLE app_users ENABLE ROW LEVEL SECURITY;\nALTER TABLE patients ENABLE ROW LEVEL SECURITY;\nALTER TABLE partner_grants ENABLE ROW LEVEL SECURITY;\nALTER TABLE cycles ENABLE ROW LEVEL SECURITY;\nALTER TABLE med_orders ENABLE ROW LEVEL SECURITY;\nALTER TABLE dose_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE clinic_ranges ENABLE ROW LEVEL SECURITY;\nALTER TABLE lab_results ENABLE ROW LEVEL SECURITY;\nALTER TABLE protocol_sections ENABLE ROW LEVEL SECURITY;\nALTER TABLE handoffs ENABLE ROW LEVEL SECURITY;\nALTER TABLE consents ENABLE ROW LEVEL SECURITY;\nALTER TABLE audit_events ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY own_clinic ON clinics FOR SELECT USING (id = kp_clinic());\nCREATE POLICY same_clinic ON app_users FOR SELECT USING (clinic_id = kp_clinic());\n\nCREATE POLICY see_patient ON patients FOR SELECT USING (\n  clinic_id = kp_clinic() AND (\n    kp_can_view(id, 'schedule') OR kp_can_view(id, 'meds') OR kp_can_view(id, 'results')\n    OR kp_can_view(id, 'money') OR kp_can_view(id, 'record')));\n\nCREATE POLICY see_grants ON partner_grants FOR SELECT USING (\n  clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR partner_user_id = kp_user() OR kp_is_clinician()));\nCREATE POLICY patient_grants ON partner_grants FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY patient_revokes ON partner_grants FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\n\nCREATE POLICY see_cycles ON cycles FOR SELECT USING (kp_can_view(patient_id, 'schedule'));\nCREATE POLICY see_meds ON med_orders FOR SELECT USING (kp_can_view(patient_id, 'meds'));\nCREATE POLICY see_doses ON dose_logs FOR SELECT USING (kp_can_view(patient_id, 'meds'));\nCREATE POLICY log_doses ON dose_logs FOR UPDATE USING (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_clinician()));\n\nCREATE POLICY see_ranges ON clinic_ranges FOR SELECT USING (clinic_id = kp_clinic());\nCREATE POLICY see_results ON lab_results FOR SELECT USING (kp_can_view(patient_id, 'results'));\nCREATE POLICY enter_results ON lab_results FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician() AND entered_by = kp_user());\n\nCREATE POLICY see_protocol ON protocol_sections FOR SELECT USING (clinic_id = kp_clinic());\n\nCREATE POLICY see_handoffs ON handoffs FOR SELECT USING (kp_can_view(patient_id, 'messages'));\nCREATE POLICY patient_writes ON handoffs FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_clinician()));\nCREATE POLICY clinician_updates ON handoffs FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY patient_reads ON handoffs FOR UPDATE\n  USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND status = 'sent')\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND status = 'read');\n\n-- Patients may only mark replies read and log their own doses; every other column is locked to them.\nCREATE FUNCTION kp_patient_handoff_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF kp_role() = 'patient' AND (\n       NEW.patient_message IS DISTINCT FROM OLD.patient_message OR NEW.kind IS DISTINCT FROM OLD.kind\n    OR NEW.triage IS DISTINCT FROM OLD.triage OR NEW.draft IS DISTINCT FROM OLD.draft\n    OR NEW.sent_text IS DISTINCT FROM OLD.sent_text OR NEW.sent_by IS DISTINCT FROM OLD.sent_by\n    OR NEW.sent_at IS DISTINCT FROM OLD.sent_at) THEN\n    RAISE EXCEPTION 'patients can only mark a reply as read';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE FUNCTION kp_patient_dose_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF kp_role() = 'patient' AND (\n       NEW.scheduled_for IS DISTINCT FROM OLD.scheduled_for OR NEW.med_order_id IS DISTINCT FROM OLD.med_order_id\n    OR NEW.patient_id IS DISTINCT FROM OLD.patient_id) THEN\n    RAISE EXCEPTION 'patients can only log or report a dose';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER handoffs_patient_guard BEFORE UPDATE ON handoffs FOR EACH ROW EXECUTE FUNCTION kp_patient_handoff_guard();\nCREATE TRIGGER doses_patient_guard BEFORE UPDATE ON dose_logs FOR EACH ROW EXECUTE FUNCTION kp_patient_dose_guard();\n\nCREATE POLICY see_consents ON consents FOR SELECT USING (kp_can_view(patient_id, 'record'));\nCREATE POLICY sign_consents ON consents FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND signed_by = kp_user());\n\n-- Audit log: anyone can append for themselves in their clinic; only clinic admins read it;\n-- no one can change or delete it (no UPDATE or DELETE policy exists, and grants are withheld below).\nCREATE POLICY append_audit ON audit_events FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND actor_user_id = kp_user());\nCREATE POLICY read_audit ON audit_events FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin');\n\n-- ---------- grants to the app role ----------\nGRANT SELECT ON ALL TABLES IN SCHEMA public TO kp_app;\nGRANT INSERT ON partner_grants, lab_results, handoffs, consents, audit_events TO kp_app;\nGRANT UPDATE ON partner_grants, dose_logs, handoffs TO kp_app;\nGRANT USAGE ON SEQUENCE audit_events_id_seq TO kp_app;\nGRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO kp_app;\n" },
  { name: "002_guides_and_prefs.sql", sql: "-- Injection walkthroughs (written and approved by the clinic's nurses) and patient reminder settings.\n\nCREATE TABLE med_guides (\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  medication text NOT NULL,\n  -- [{ \"en\": \"...\", \"es\": \"...\" }, ...] in order\n  steps jsonb NOT NULL,\n  video_url text,\n  approved_by text NOT NULL,\n  PRIMARY KEY (clinic_id, medication)\n);\n\nCREATE TABLE patient_prefs (\n  patient_id uuid PRIMARY KEY REFERENCES patients(id),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  lead_minutes int NOT NULL DEFAULT 15 CHECK (lead_minutes BETWEEN 0 AND 120),\n  follow_up_minutes int NOT NULL DEFAULT 60 CHECK (follow_up_minutes BETWEEN 15 AND 240),\n  quiet_start time NOT NULL DEFAULT '21:30',\n  quiet_end time NOT NULL DEFAULT '07:00',\n  lock_screen_detail boolean NOT NULL DEFAULT false\n);\n\nALTER TABLE med_guides ENABLE ROW LEVEL SECURITY;\nALTER TABLE patient_prefs ENABLE ROW LEVEL SECURITY;\n\n-- Guides are clinic content, not patient data: anyone in the clinic can read them.\nCREATE POLICY see_guides ON med_guides FOR SELECT USING (clinic_id = kp_clinic());\n\nCREATE POLICY own_prefs_read ON patient_prefs FOR SELECT USING (kp_is_patient_self(patient_id));\nCREATE POLICY own_prefs_insert ON patient_prefs FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_prefs_update ON patient_prefs FOR UPDATE USING (kp_is_patient_self(patient_id));\n\nGRANT SELECT ON med_guides, patient_prefs TO kp_app;\nGRANT INSERT, UPDATE ON patient_prefs TO kp_app;\n" },
  { name: "003_clinic_settings.sql", sql: "-- Clinic settings: nurses and physicians edit what patients see, and every change is recorded.\n\nALTER TABLE med_guides ADD COLUMN sort_order int NOT NULL DEFAULT 100;\nALTER TABLE med_guides ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE clinic_ranges ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();\nALTER TABLE protocol_sections ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();\n\n-- Extra urgent words a clinic adds. Built-in rules live in code and can't be removed.\nCREATE TABLE clinic_triage_terms (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  term text NOT NULL,\n  level text NOT NULL CHECK (level IN ('urgent','crisis')),\n  added_by text NOT NULL,\n  added_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (clinic_id, term)\n);\n\n-- Who changed which piece of patient-facing content, from what, to what. Append-only.\nCREATE TABLE content_changes (\n  id bigserial PRIMARY KEY,\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  changed_by uuid NOT NULL REFERENCES app_users(id),\n  changed_by_name text NOT NULL,\n  area text NOT NULL CHECK (area IN ('range','protocol','walkthrough','urgent_word')),\n  item text NOT NULL,\n  action text NOT NULL CHECK (action IN ('created','updated','removed','reordered')),\n  before jsonb,\n  after jsonb,\n  at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE clinic_triage_terms ENABLE ROW LEVEL SECURITY;\nALTER TABLE content_changes ENABLE ROW LEVEL SECURITY;\n\n-- Staff in the clinic can read settings; patients don't need the raw term list.\nCREATE POLICY see_terms ON clinic_triage_terms FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() NOT IN ('patient','partner'));\n-- The server applies clinic terms to patient messages; patients need read access only inside that check.\nCREATE POLICY patient_terms ON clinic_triage_terms FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() = 'patient');\nCREATE POLICY edit_terms ON clinic_triage_terms FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY drop_terms ON clinic_triage_terms FOR DELETE USING (clinic_id = kp_clinic() AND kp_is_clinician());\n\nCREATE POLICY edit_ranges ON clinic_ranges FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY update_ranges ON clinic_ranges FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY drop_ranges ON clinic_ranges FOR DELETE USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY edit_protocol ON protocol_sections FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY update_protocol ON protocol_sections FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY update_guides ON med_guides FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician());\n\nCREATE POLICY see_changes ON content_changes FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() IN ('nurse','physician','clinic_admin'));\nCREATE POLICY log_changes ON content_changes FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician() AND changed_by = kp_user());\n\nGRANT SELECT, INSERT, DELETE ON clinic_triage_terms TO kp_app;\nGRANT SELECT, INSERT ON content_changes TO kp_app;\nGRANT USAGE ON SEQUENCE content_changes_id_seq TO kp_app;\nGRANT INSERT, UPDATE, DELETE ON clinic_ranges TO kp_app;\nGRANT INSERT, UPDATE ON protocol_sections TO kp_app;\nGRANT UPDATE ON med_guides TO kp_app;\n" },
  { name: "004_partner.sql", sql: "-- Partner side: short notes from a partner to the patient, and the patient's sharing controls.\n-- Notes are private between the two of them. Clinic staff can't read them, so they never become\n-- a clinical record. A partner who mentions an urgent symptom is told to call, right in the app.\n\nCREATE FUNCTION kp_is_partner_of(p_patient uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT kp_role() = 'partner' AND EXISTS (\n    SELECT 1 FROM partner_grants g\n    WHERE g.patient_id = p_patient AND g.partner_user_id = kp_user() AND g.clinic_id = kp_clinic()\n      AND g.revoked_at IS NULL AND cardinality(g.sections) > 0)\n$$;\n\n-- The patient can see her partner's name; the partner can see the patient's name.\nCREATE FUNCTION kp_partner_names(p_patient uuid)\nRETURNS TABLE (partner_user_id uuid, partner_name text, sections text[], revoked boolean)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT g.partner_user_id, u.display_name, g.sections, g.revoked_at IS NOT NULL\n  FROM partner_grants g JOIN app_users u ON u.id = g.partner_user_id\n  WHERE g.patient_id = p_patient AND g.clinic_id = kp_clinic() AND kp_is_patient_self(p_patient)\n  ORDER BY g.created_at\n$$;\n\nCREATE TABLE partner_notes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  from_user_id uuid NOT NULL REFERENCES app_users(id),\n  from_name text NOT NULL,\n  body text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 500),\n  -- Triage of the note's words. An urgent note shows the patient a \"call the nurse line\" card, not \"Thanks\".\n  level text NOT NULL DEFAULT 'routine' CHECK (level IN ('routine','urgent','crisis')),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  seen_at timestamptz\n);\n\nALTER TABLE partner_notes ENABLE ROW LEVEL SECURITY;\nCREATE POLICY read_notes ON partner_notes FOR SELECT USING (\n  clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR from_user_id = kp_user()));\nCREATE POLICY write_notes ON partner_notes FOR INSERT WITH CHECK (\n  clinic_id = kp_clinic() AND from_user_id = kp_user() AND kp_is_partner_of(patient_id));\nCREATE POLICY see_notes ON partner_notes FOR UPDATE\n  USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id))\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\n\n-- The patient may only mark a note seen.\nCREATE FUNCTION kp_note_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF NEW.body IS DISTINCT FROM OLD.body OR NEW.from_user_id IS DISTINCT FROM OLD.from_user_id\n     OR NEW.from_name IS DISTINCT FROM OLD.from_name OR NEW.patient_id IS DISTINCT FROM OLD.patient_id\n     OR NEW.level IS DISTINCT FROM OLD.level\n     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n    RAISE EXCEPTION 'notes can only be marked seen';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER notes_guard BEFORE UPDATE ON partner_notes FOR EACH ROW EXECUTE FUNCTION kp_note_guard();\n\n-- A partner can never change grants, even his own (the existing policy already limits UPDATE to\n-- the patient). Sections stay limited by the CHECK on partner_grants: messages can never be shared.\n\n-- Partners' notes are checked against the clinic's added urgent words too.\nCREATE POLICY partner_terms ON clinic_triage_terms FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() = 'partner');\n\nGRANT SELECT, INSERT, UPDATE ON partner_notes TO kp_app;\nGRANT EXECUTE ON FUNCTION kp_is_partner_of(uuid), kp_partner_names(uuid) TO kp_app;\n" },
  { name: "005_support_invites.sql", sql: "-- Support people: a patient invites a partner, family member or friend and picks what they see.\n-- An invite is a one-time code that expires in 7 days. Only a hash of the code is stored.\n\nALTER TABLE partner_grants ADD COLUMN relationship text NOT NULL DEFAULT 'partner'\n  CHECK (relationship IN ('partner','family','friend','other'));\n-- Removing someone ends their access and takes them off the patient's list.\n-- (Switching every section off only pauses access; the person stays on her list.)\nALTER TABLE partner_grants ADD COLUMN removed_at timestamptz;\n\nCREATE TABLE support_invites (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  invited_by uuid NOT NULL REFERENCES app_users(id),\n  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),\n  relationship text NOT NULL CHECK (relationship IN ('partner','family','friend','other')),\n  contact text NOT NULL CHECK (char_length(contact) BETWEEN 3 AND 200),\n  sections text[] NOT NULL CHECK (sections <@ ARRAY['schedule','meds','results']::text[] AND cardinality(sections) > 0),\n  code_hash text NOT NULL UNIQUE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL DEFAULT now() + interval '7 days',\n  accepted_at timestamptz,\n  accepted_user_id uuid REFERENCES app_users(id),\n  canceled_at timestamptz\n);\n\nALTER TABLE support_invites ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_invites_read ON support_invites FOR SELECT USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_invites_add ON support_invites FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND invited_by = kp_user());\nCREATE POLICY own_invites_cancel ON support_invites FOR UPDATE\n  USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id))\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\n\n-- Through the app role, a patient may only cancel an invite. Accepting runs in kp_accept_invite.\nCREATE FUNCTION kp_invite_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF current_user = 'kp_app' AND (\n       NEW.code_hash IS DISTINCT FROM OLD.code_hash OR NEW.sections IS DISTINCT FROM OLD.sections\n    OR NEW.patient_id IS DISTINCT FROM OLD.patient_id OR NEW.expires_at IS DISTINCT FROM OLD.expires_at\n    OR NEW.accepted_at IS DISTINCT FROM OLD.accepted_at OR NEW.accepted_user_id IS DISTINCT FROM OLD.accepted_user_id\n    OR NEW.contact IS DISTINCT FROM OLD.contact OR NEW.name IS DISTINCT FROM OLD.name) THEN\n    RAISE EXCEPTION 'an invite can only be canceled';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER invites_guard BEFORE UPDATE ON support_invites FOR EACH ROW EXECUTE FUNCTION kp_invite_guard();\n\n-- Grant checks now also respect removal.\nCREATE OR REPLACE FUNCTION kp_can_view(p_patient uuid, p_section text) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM patients p\n    WHERE p.id = p_patient AND p.clinic_id = kp_clinic()\n      AND (\n        (kp_role() = 'patient' AND p.user_id = kp_user())\n        OR (kp_role() = 'partner' AND p_section <> 'messages' AND EXISTS (\n              SELECT 1 FROM partner_grants g\n              WHERE g.patient_id = p.id AND g.partner_user_id = kp_user()\n                AND g.revoked_at IS NULL AND g.removed_at IS NULL AND p_section = ANY (g.sections)))\n        OR (p_section = ANY (kp_staff_sections(kp_role())))\n      )\n  )\n$$;\n\nCREATE OR REPLACE FUNCTION kp_is_partner_of(p_patient uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT kp_role() = 'partner' AND EXISTS (\n    SELECT 1 FROM partner_grants g\n    WHERE g.patient_id = p_patient AND g.partner_user_id = kp_user() AND g.clinic_id = kp_clinic()\n      AND g.revoked_at IS NULL AND g.removed_at IS NULL AND cardinality(g.sections) > 0)\n$$;\n\nDROP FUNCTION kp_partner_names(uuid);\nCREATE FUNCTION kp_partner_names(p_patient uuid)\nRETURNS TABLE (partner_user_id uuid, partner_name text, relationship text, sections text[], revoked boolean)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT g.partner_user_id, u.display_name, g.relationship, g.sections, g.revoked_at IS NOT NULL\n  FROM partner_grants g JOIN app_users u ON u.id = g.partner_user_id\n  WHERE g.patient_id = p_patient AND g.clinic_id = kp_clinic() AND g.removed_at IS NULL AND kp_is_patient_self(p_patient)\n  ORDER BY g.created_at\n$$;\n\n-- Accepting an invite is the one step that happens before the person has an account, like a\n-- sign-up service would. It checks the code's hash, creates the support person and their access\n-- in one transaction, and records it in the audit log. Before launch: rate-limit this endpoint and\n-- confirm the person's phone or email with a one-time sign-in link.\nCREATE FUNCTION kp_accept_invite(p_hash text, p_name text)\nRETURNS TABLE (user_id uuid, clinic_id text, patient_first_name text)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  inv support_invites%ROWTYPE;\n  new_user uuid;\nBEGIN\n  SELECT * INTO inv FROM support_invites i WHERE i.code_hash = p_hash FOR UPDATE;\n  IF NOT FOUND OR inv.accepted_at IS NOT NULL OR inv.canceled_at IS NOT NULL OR inv.expires_at < now() THEN\n    RAISE EXCEPTION 'invite_invalid';\n  END IF;\n  IF char_length(trim(p_name)) NOT BETWEEN 1 AND 80 THEN\n    RAISE EXCEPTION 'name_invalid';\n  END IF;\n  -- The contact (phone or email) is the person's sign-in identifier.\n  IF EXISTS (SELECT 1 FROM app_users u WHERE u.clinic_id = inv.clinic_id AND u.email = lower(inv.contact)) THEN\n    RAISE EXCEPTION 'already_connected';\n  END IF;\n  INSERT INTO app_users (clinic_id, role, display_name, email) VALUES (inv.clinic_id, 'partner', trim(p_name), lower(inv.contact))\n    RETURNING id INTO new_user;\n  INSERT INTO partner_grants (clinic_id, patient_id, partner_user_id, sections, relationship)\n    VALUES (inv.clinic_id, inv.patient_id, new_user, inv.sections, inv.relationship);\n  UPDATE support_invites SET accepted_at = now(), accepted_user_id = new_user WHERE id = inv.id;\n  INSERT INTO audit_events (clinic_id, actor_user_id, action, patient_id, detail)\n    VALUES (inv.clinic_id, new_user, 'support.accepted_invite', inv.patient_id, jsonb_build_object('inviteId', inv.id, 'relationship', inv.relationship));\n  RETURN QUERY SELECT new_user, inv.clinic_id, p.first_name FROM patients p WHERE p.id = inv.patient_id;\nEND $$;\nREVOKE EXECUTE ON FUNCTION kp_accept_invite(text, text) FROM PUBLIC, kp_app;\n\nGRANT SELECT, INSERT, UPDATE ON support_invites TO kp_app;\nGRANT EXECUTE ON FUNCTION kp_partner_names(uuid) TO kp_app;\n" },
  { name: "006_wait_and_result.sql", sql: "-- The two-week wait and result day.\n--\n-- Safety rules this schema enforces:\n-- 1. A pregnancy test result is invisible to the patient until a nurse or physician releases it.\n--    Patients never read pregnancy_tests directly; they go through kp_pregnancy_test_view().\n-- 2. Support people never see a result, even after release. The patient tells them herself.\n-- 3. The outcome (positive / negative / needs a repeat) is a clinician's decision, entered by\n--    hand. Kinpath never computes it from the hCG number.\n\n-- Stimulation doses after a transfer are canceled, not deleted, so the record stays complete.\nALTER TABLE dose_logs ADD COLUMN canceled_at timestamptz;\nALTER TABLE cycles ADD COLUMN transfer_on date;\n\nCREATE POLICY clinician_cycles ON cycles FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician());\nGRANT UPDATE ON cycles TO kp_app;\n\nCREATE TABLE pregnancy_tests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  cycle_id uuid NOT NULL REFERENCES cycles(id),\n  scheduled_at timestamptz NOT NULL,\n  hcg numeric,\n  outcome text CHECK (outcome IN ('positive','negative','repeat')),\n  nurse_note text CHECK (char_length(nurse_note) <= 1000),\n  entered_by_name text,\n  released_at timestamptz,\n  released_by_name text,\n  -- How the patient heard: 'phone' (the nurse called first) or 'app'.\n  told_by text CHECK (told_by IN ('phone','app')),\n  CHECK (released_at IS NULL OR (outcome IS NOT NULL AND nurse_note IS NOT NULL AND char_length(nurse_note) > 0))\n);\nALTER TABLE pregnancy_tests ENABLE ROW LEVEL SECURITY;\nCREATE POLICY clinician_tests ON pregnancy_tests FOR ALL\n  USING (clinic_id = kp_clinic() AND kp_is_clinician())\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nGRANT SELECT, INSERT, UPDATE ON pregnancy_tests TO kp_app;\n\n-- What a patient or support person may know about the latest test.\nCREATE FUNCTION kp_pregnancy_test_view(p_patient uuid)\nRETURNS TABLE (scheduled_at timestamptz, released boolean, outcome text, hcg numeric, nurse_note text, released_by_name text, released_at timestamptz)\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT t.scheduled_at,\n         t.released_at IS NOT NULL,\n         CASE WHEN kp_is_patient_self(p_patient) AND t.released_at IS NOT NULL THEN t.outcome END,\n         CASE WHEN kp_is_patient_self(p_patient) AND t.released_at IS NOT NULL THEN t.hcg END,\n         CASE WHEN kp_is_patient_self(p_patient) AND t.released_at IS NOT NULL THEN t.nurse_note END,\n         CASE WHEN kp_is_patient_self(p_patient) AND t.released_at IS NOT NULL THEN t.released_by_name END,\n         CASE WHEN kp_is_patient_self(p_patient) AND t.released_at IS NOT NULL THEN t.released_at END\n  FROM pregnancy_tests t\n  WHERE t.patient_id = p_patient AND t.clinic_id = kp_clinic()\n    AND (kp_is_patient_self(p_patient) OR kp_can_view(p_patient, 'schedule'))\n  ORDER BY t.scheduled_at DESC LIMIT 1\n$$;\n\n-- The patient's choices for the wait.\nCREATE TABLE wait_prefs (\n  patient_id uuid PRIMARY KEY REFERENCES patients(id),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  result_how text CHECK (result_how IN ('call','app','together')),\n  hide_day_count boolean NOT NULL DEFAULT false,\n  -- After a negative result the app goes quiet for 14 days unless she turns it off.\n  quiet_off boolean NOT NULL DEFAULT false,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE wait_prefs ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_wait_read ON wait_prefs FOR SELECT USING (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_clinician()));\nCREATE POLICY own_wait_add ON wait_prefs FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_wait_change ON wait_prefs FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT, UPDATE ON wait_prefs TO kp_app;\n\n-- A support person only learns whether she hid the day count (so they don't show it either).\nCREATE FUNCTION kp_hide_day_count(p_patient uuid) RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT coalesce((SELECT hide_day_count FROM wait_prefs w WHERE w.patient_id = p_patient AND w.clinic_id = kp_clinic()\n                   AND (kp_is_patient_self(p_patient) OR kp_can_view(p_patient, 'schedule'))), false)\n$$;\n\n-- Daily \"How are you today?\"\nCREATE TABLE wellbeing_checkins (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  feeling text NOT NULL CHECK (feeling IN ('okay','anxious','struggling')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE wellbeing_checkins ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_checkins_read ON wellbeing_checkins FOR SELECT USING (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_clinician()));\nCREATE POLICY own_checkins_add ON wellbeing_checkins FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT ON wellbeing_checkins TO kp_app;\n\n-- Internal nurse tasks (calls to make). Patients can ask for a call but can never read the list.\nCREATE TABLE nurse_tasks (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('wellbeing_call','result_call','negative_followup')),\n  reason text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  done_at timestamptz,\n  done_by_name text,\n  done_note text\n);\nALTER TABLE nurse_tasks ENABLE ROW LEVEL SECURITY;\nCREATE POLICY clinician_tasks ON nurse_tasks FOR ALL\n  USING (clinic_id = kp_clinic() AND kp_is_clinician())\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY patient_asks_call ON nurse_tasks FOR INSERT\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND kind = 'wellbeing_call' AND done_at IS NULL);\nGRANT SELECT, INSERT, UPDATE ON nurse_tasks TO kp_app;\n-- INSERT ... RETURNING needs SELECT; patients don't get it, so their inserts don't use RETURNING.\n" },
  { name: "007_graduation.sql", sql: "-- Graduation to the OB-GYN, the shareable IVF pregnancy summary, the keepsake, and thank-you notes.\n\nALTER TABLE cycles ADD COLUMN graduated_on date;\nALTER TABLE cycles ADD COLUMN ob_name text CHECK (char_length(ob_name) <= 120);\n\n-- The patient decides when her support people learn her result.\nALTER TABLE wait_prefs ADD COLUMN told_support boolean NOT NULL DEFAULT false;\n\n-- What a support person may know about the outcome: nothing until the patient shares the news.\nCREATE FUNCTION kp_shared_news(p_patient uuid) RETURNS text\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT CASE\n    WHEN NOT kp_can_view(p_patient, 'schedule') THEN NULL\n    WHEN NOT coalesce((SELECT told_support FROM wait_prefs WHERE patient_id = p_patient), false) THEN NULL\n    WHEN (SELECT graduated_on FROM cycles WHERE patient_id = p_patient ORDER BY started_on DESC LIMIT 1) IS NOT NULL THEN 'graduated'\n    ELSE (SELECT outcome FROM pregnancy_tests WHERE patient_id = p_patient AND released_at IS NOT NULL ORDER BY scheduled_at DESC LIMIT 1)\n  END\n$$;\n\n-- What she keeps, and what she chose to leave out.\nCREATE TABLE keepsakes (\n  patient_id uuid PRIMARY KEY REFERENCES patients(id),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  hidden text[] NOT NULL DEFAULT '{}',\n  saved_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE keepsakes ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_keepsake_read ON keepsakes FOR SELECT USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_keepsake_add ON keepsakes FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_keepsake_change ON keepsakes FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT, UPDATE ON keepsakes TO kp_app;\n\n-- Thank-you notes to the care team. Staff read them; the patient writes them.\nCREATE TABLE thank_you_notes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  from_name text NOT NULL,\n  body text NOT NULL CHECK (char_length(body) BETWEEN 1 AND 1000),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE thank_you_notes ENABLE ROW LEVEL SECURITY;\nCREATE POLICY staff_read_thanks ON thank_you_notes FOR SELECT USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY patient_thanks ON thank_you_notes FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT ON thank_you_notes TO kp_app;\n\n-- A secure, expiring, revocable link to the IVF pregnancy summary, for the patient's OB-GYN.\n-- Only a hash of the link's token is stored. Every view is written to the audit log.\nCREATE TABLE summary_shares (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  created_by uuid NOT NULL REFERENCES app_users(id),\n  recipient text NOT NULL CHECK (char_length(recipient) BETWEEN 1 AND 120),\n  include_results boolean NOT NULL,\n  include_meds boolean NOT NULL,\n  token_hash text NOT NULL UNIQUE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL DEFAULT now() + interval '7 days',\n  revoked_at timestamptz,\n  views int NOT NULL DEFAULT 0,\n  last_viewed_at timestamptz\n);\nALTER TABLE summary_shares ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_shares_read ON summary_shares FOR SELECT USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_shares_add ON summary_shares FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND created_by = kp_user());\nCREATE POLICY own_shares_revoke ON summary_shares FOR UPDATE\n  USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id))\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE FUNCTION kp_share_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF current_user = 'kp_app' AND (\n       NEW.token_hash IS DISTINCT FROM OLD.token_hash OR NEW.expires_at IS DISTINCT FROM OLD.expires_at\n    OR NEW.include_results IS DISTINCT FROM OLD.include_results OR NEW.include_meds IS DISTINCT FROM OLD.include_meds\n    OR NEW.patient_id IS DISTINCT FROM OLD.patient_id OR NEW.recipient IS DISTINCT FROM OLD.recipient\n    OR NEW.views IS DISTINCT FROM OLD.views) THEN\n    RAISE EXCEPTION 'a shared link can only be stopped';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER shares_guard BEFORE UPDATE ON summary_shares FOR EACH ROW EXECUTE FUNCTION kp_share_guard();\nGRANT SELECT, INSERT, UPDATE ON summary_shares TO kp_app;\n\n-- Opening a summary link. Runs without a signed-in user, so it lives in one narrow function:\n-- it checks the token, builds the summary from exactly what the patient chose to include,\n-- counts the view and writes it to the audit log.\nCREATE FUNCTION kp_open_summary(p_hash text) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  s summary_shares%ROWTYPE;\n  pat patients%ROWTYPE;\n  cyc cycles%ROWTYPE;\n  out jsonb;\nBEGIN\n  SELECT * INTO s FROM summary_shares WHERE token_hash = p_hash FOR UPDATE;\n  IF NOT FOUND OR s.revoked_at IS NOT NULL OR s.expires_at < now() THEN\n    RETURN NULL;\n  END IF;\n  SELECT * INTO pat FROM patients WHERE id = s.patient_id;\n  SELECT * INTO cyc FROM cycles WHERE patient_id = s.patient_id ORDER BY started_on DESC LIMIT 1;\n  out := jsonb_build_object(\n    'patient', pat.first_name || ' ' || pat.last_name,\n    'clinic', (SELECT name FROM clinics WHERE id = s.clinic_id),\n    'recipient', s.recipient,\n    'expiresAt', s.expires_at,\n    'cycle', jsonb_build_object('kind', cyc.kind, 'startedOn', cyc.started_on, 'transferOn', cyc.transfer_on, 'graduatedOn', cyc.graduated_on, 'ob', cyc.ob_name),\n    'tests', CASE WHEN s.include_results THEN coalesce((\n        SELECT jsonb_agg(jsonb_build_object('at', least(t.scheduled_at, t.released_at), 'hcg', t.hcg, 'outcome', t.outcome) ORDER BY t.scheduled_at)\n        FROM pregnancy_tests t WHERE t.patient_id = s.patient_id AND t.released_at IS NOT NULL), '[]'::jsonb) END,\n    'labs', CASE WHEN s.include_results THEN coalesce((\n        SELECT jsonb_agg(jsonb_build_object('analyte', l.analyte, 'value', l.value, 'unit', l.unit, 'stimDay', l.stim_day, 'at', l.collected_at) ORDER BY l.collected_at)\n        FROM lab_results l WHERE l.patient_id = s.patient_id), '[]'::jsonb) END,\n    'meds', CASE WHEN s.include_meds THEN coalesce((\n        SELECT jsonb_agg(jsonb_build_object('medication', m.medication, 'dose', m.dose,\n                 'taken', (SELECT count(*) FROM dose_logs d WHERE d.med_order_id = m.id AND d.taken_at IS NOT NULL)) ORDER BY m.medication)\n        FROM med_orders m WHERE m.patient_id = s.patient_id), '[]'::jsonb) END\n  );\n  UPDATE summary_shares SET views = views + 1, last_viewed_at = now() WHERE id = s.id;\n  INSERT INTO audit_events (clinic_id, actor_user_id, action, patient_id, detail)\n    VALUES (s.clinic_id, s.created_by, 'summary.viewed_by_link', s.patient_id, jsonb_build_object('shareId', s.id, 'recipient', s.recipient));\n  RETURN out;\nEND $$;\nREVOKE EXECUTE ON FUNCTION kp_open_summary(text) FROM PUBLIC, kp_app;\nGRANT EXECUTE ON FUNCTION kp_shared_news(uuid) TO kp_app;\n" },
  { name: "008_next_cycle.sql", sql: "-- \"When you're ready\": planning a next cycle after a negative result, at the patient's pace.\n\n-- Embryos frozen at the time of transfer (pilot entry until the records-system connection).\nALTER TABLE cycles ADD COLUMN embryos_frozen int CHECK (embryos_frozen BETWEEN 0 AND 50);\n\n-- New kinds of calls: the patient says she's ready to talk about next steps.\nALTER TABLE nurse_tasks DROP CONSTRAINT nurse_tasks_kind_check;\nALTER TABLE nurse_tasks ADD CONSTRAINT nurse_tasks_kind_check CHECK (kind IN ('wellbeing_call','result_call','negative_followup','next_steps'));\nDROP POLICY patient_asks_call ON nurse_tasks;\nCREATE POLICY patient_asks_call ON nurse_tasks FOR INSERT\n  WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND kind IN ('wellbeing_call','next_steps') AND done_at IS NULL);\n\n-- Her own questions for the follow-up visit, and when she said she was ready.\nCREATE TABLE next_cycle_plans (\n  patient_id uuid PRIMARY KEY REFERENCES patients(id),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  questions text NOT NULL DEFAULT '' CHECK (char_length(questions) <= 2000),\n  ready_at timestamptz,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE next_cycle_plans ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_plan_read ON next_cycle_plans FOR SELECT USING (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_clinician()));\nCREATE POLICY own_plan_add ON next_cycle_plans FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_plan_change ON next_cycle_plans FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT, UPDATE ON next_cycle_plans TO kp_app;\n" },
  { name: "009_accounts_and_notifications.sql", sql: "-- Real sign-in, account settings, team management and notifications.\n\n-- ---------- people ----------\nALTER TABLE app_users ADD COLUMN deactivated_at timestamptz;\nALTER TABLE app_users ADD COLUMN title text CHECK (char_length(title) <= 80);\nALTER TABLE app_users ADD COLUMN signature text CHECK (char_length(signature) <= 200);\n\n-- Staff can edit their own profile; clinic admins manage staff (not patients). A trigger limits\n-- exactly which columns each can change.\nCREATE POLICY self_profile ON app_users FOR UPDATE USING (id = kp_user()) WITH CHECK (id = kp_user());\nCREATE POLICY admin_manages_staff ON app_users FOR UPDATE\n  USING (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin')\n  WITH CHECK (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin');\nCREATE POLICY admin_adds_staff ON app_users FOR INSERT\n  WITH CHECK (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin' AND role NOT IN ('patient','partner'));\nGRANT INSERT, UPDATE ON app_users TO kp_app;\n\nCREATE FUNCTION kp_user_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF current_user <> 'kp_app' THEN RETURN NEW; END IF;\n  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.clinic_id IS DISTINCT FROM OLD.clinic_id OR NEW.email IS DISTINCT FROM OLD.email THEN\n    RAISE EXCEPTION 'that can''t be changed here';\n  END IF;\n  IF OLD.id = kp_user() THEN\n    -- Your own profile: name, title, signature, language. Never your own role or status.\n    IF NEW.role IS DISTINCT FROM OLD.role OR NEW.deactivated_at IS DISTINCT FROM OLD.deactivated_at THEN\n      RAISE EXCEPTION 'you can''t change your own role or status';\n    END IF;\n  ELSE\n    -- An admin managing someone else: staff only; role, status, name and title only.\n    IF OLD.role IN ('patient','partner') OR NEW.role IN ('patient','partner') THEN\n      RAISE EXCEPTION 'admins manage staff accounts only';\n    END IF;\n    IF NEW.signature IS DISTINCT FROM OLD.signature OR NEW.preferred_lang IS DISTINCT FROM OLD.preferred_lang THEN\n      RAISE EXCEPTION 'only the person can change that';\n    END IF;\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER users_guard BEFORE UPDATE ON app_users FOR EACH ROW EXECUTE FUNCTION kp_user_guard();\n\n-- ---------- sign-in (auth service only: the app role has no access at all) ----------\nCREATE TABLE user_credentials (\n  user_id uuid PRIMARY KEY REFERENCES app_users(id),\n  password_hash text,\n  password_changed_at timestamptz,\n  totp_secret text,\n  totp_enabled_at timestamptz\n);\nCREATE TABLE sessions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  token_hash text NOT NULL UNIQUE,\n  user_id uuid NOT NULL REFERENCES app_users(id),\n  kind text NOT NULL CHECK (kind IN ('staff','patient')),\n  device text,\n  mfa_passed boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  last_seen_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL,\n  revoked_at timestamptz\n);\nCREATE TABLE sign_in_codes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  purpose text NOT NULL CHECK (purpose IN ('sign_in','join','setup')),\n  user_id uuid REFERENCES app_users(id),\n  invite_id uuid REFERENCES support_invites(id),\n  join_name text,\n  code_hash text NOT NULL,\n  attempts int NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL,\n  used_at timestamptz\n);\nCREATE TABLE auth_failures (\n  identifier text NOT NULL,\n  at timestamptz NOT NULL DEFAULT now()\n);\nCREATE INDEX auth_failures_idx ON auth_failures (identifier, at);\nREVOKE ALL ON user_credentials, sessions, sign_in_codes, auth_failures FROM kp_app;\n\n-- ---------- notifications ----------\nCREATE TABLE notifications (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  user_id uuid NOT NULL REFERENCES app_users(id),\n  kind text NOT NULL,\n  title text NOT NULL,\n  link text,\n  urgent boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  read_at timestamptz\n);\nALTER TABLE notifications ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_notifications ON notifications FOR SELECT USING (user_id = kp_user() AND clinic_id = kp_clinic());\nCREATE POLICY read_notifications ON notifications FOR UPDATE USING (user_id = kp_user()) WITH CHECK (user_id = kp_user());\nGRANT SELECT, UPDATE ON notifications TO kp_app;\nCREATE FUNCTION kp_notification_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF current_user = 'kp_app' AND (NEW.title IS DISTINCT FROM OLD.title OR NEW.kind IS DISTINCT FROM OLD.kind\n     OR NEW.link IS DISTINCT FROM OLD.link OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.urgent IS DISTINCT FROM OLD.urgent) THEN\n    RAISE EXCEPTION 'notifications can only be marked read';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER notifications_guard BEFORE UPDATE ON notifications FOR EACH ROW EXECUTE FUNCTION kp_notification_guard();\n\nCREATE TABLE notification_prefs (\n  user_id uuid NOT NULL REFERENCES app_users(id),\n  kind text NOT NULL,\n  in_app boolean, push boolean, sms boolean, email boolean,\n  PRIMARY KEY (user_id, kind)\n);\nCREATE TABLE user_settings (\n  user_id uuid PRIMARY KEY REFERENCES app_users(id),\n  quiet_on boolean NOT NULL DEFAULT false,\n  quiet_start time NOT NULL DEFAULT '21:00',\n  quiet_end time NOT NULL DEFAULT '07:00',\n  digest text NOT NULL DEFAULT 'off' CHECK (digest IN ('off','morning','evening')),\n  phone text CHECK (char_length(phone) <= 30)\n);\nALTER TABLE notification_prefs ENABLE ROW LEVEL SECURITY;\nALTER TABLE user_settings ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_prefs ON notification_prefs FOR ALL USING (user_id = kp_user()) WITH CHECK (user_id = kp_user());\nCREATE POLICY own_settings ON user_settings FOR ALL USING (user_id = kp_user()) WITH CHECK (user_id = kp_user());\nGRANT SELECT, INSERT, UPDATE ON notification_prefs, user_settings TO kp_app;\n\n-- What would be sent by push, text or email. Health details never appear here.\n-- Until a texting and an email service are connected (each with a signed HIPAA agreement),\n-- nothing leaves the building: the dev outbox page shows what would have gone out.\nCREATE TABLE outbox (\n  id bigserial PRIMARY KEY,\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  user_id uuid REFERENCES app_users(id),\n  channel text NOT NULL CHECK (channel IN ('push','sms','email')),\n  to_address text,\n  subject text NOT NULL,\n  body text NOT NULL,\n  status text NOT NULL CHECK (status IN ('send','held','digest','sent')),\n  send_after timestamptz NOT NULL DEFAULT now(),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nREVOKE ALL ON outbox FROM kp_app;\nREVOKE ALL ON outbox_id_seq FROM kp_app;\n" },
  { name: "010_production_role.sql", sql: "-- On managed Postgres the connecting user isn't a superuser, so it needs membership in kp_app\n-- to switch into it inside each request (SET LOCAL ROLE kp_app). Harmless where it already has it.\nDO $$\nBEGIN\n  EXECUTE format('GRANT kp_app TO %I', current_user);\nEXCEPTION WHEN others THEN\n  NULL;\nEND $$;\n" },
  { name: "011_ai_drafts.sql", sql: "-- How each draft was made, and why an AI draft was held back (if it was). Never the AI's raw text.\nALTER TABLE handoffs ADD COLUMN draft_engine text CHECK (draft_engine IN ('protocol','ai','ai_held_back','ai_error'));\nALTER TABLE handoffs ADD COLUMN draft_problems jsonb;\n" },
  { name: "012_records_connection.sql", sql: "-- Records connection: lab results and medication orders arriving from the clinic's records system\n-- (EHR) instead of being typed in.\n--\n-- Rules:\n-- 1. A record is matched to a patient by medical record number (MRN) within the clinic, and the\n--    last name must agree when the record carries one. Anything that doesn't match goes to a\n--    nurse's review list. Nothing is ever guessed.\n-- 2. Every record has an id from the records system. Sending the same record twice changes nothing.\n-- 3. Lab results go through the same labeling as typed results: in range → the patient sees the\n--    clinic's approved words; anything else → the nurse first.\n-- 4. A pregnancy blood test (hCG) only fills in the number on the unreleased test. The nurse still\n--    decides the outcome and when the patient hears it.\n-- 5. Medication orders wait for a nurse to confirm before the patient's schedule changes.\n-- 6. The connection signs in with a per-clinic key; only its hash is stored.\n\nALTER TABLE patients ADD COLUMN mrn text;\nCREATE UNIQUE INDEX patients_clinic_mrn ON patients (clinic_id, mrn) WHERE mrn IS NOT NULL;\n\nCREATE TABLE integration_keys (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),\n  key_hash text NOT NULL UNIQUE,\n  key_hint text NOT NULL,             -- last 4 characters, so admins can tell keys apart\n  created_by uuid NOT NULL REFERENCES app_users(id),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  last_used_at timestamptz,\n  revoked_at timestamptz\n);\n\nCREATE TABLE record_imports (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  key_id uuid REFERENCES integration_keys(id),\n  format text NOT NULL CHECK (format IN ('fhir','csv','sample')),\n  received_at timestamptz NOT NULL DEFAULT now(),\n  -- Counts only. No names, numbers or values, so admins can read the log.\n  counts jsonb NOT NULL DEFAULT '{}'::jsonb\n);\n\nCREATE TABLE record_items (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  import_id uuid NOT NULL REFERENCES record_imports(id),\n  external_id text NOT NULL,\n  kind text NOT NULL CHECK (kind IN ('result','hcg','med_order','med_stop')),\n  status text NOT NULL CHECK (status IN ('applied','needs_review','dismissed')),\n  reason text,\n  patient_id uuid REFERENCES patients(id),\n  mrn text,\n  -- The record as Pumpkin understood it (analyte, value, unit, date; or medication, dose, time, dates).\n  data jsonb NOT NULL,\n  lab_result_id uuid REFERENCES lab_results(id),\n  med_order_id uuid,\n  reviewed_by_name text,\n  reviewed_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX record_items_external ON record_items (clinic_id, kind, external_id);\n\n-- Typed results have a person; records-system results don't.\nALTER TABLE lab_results ALTER COLUMN entered_by DROP NOT NULL;\nALTER TABLE lab_results ADD CONSTRAINT lab_results_who CHECK (entered_by IS NOT NULL OR source <> 'staff_entry');\nALTER TABLE lab_results ADD COLUMN corrected_at timestamptz;\n\n-- Medication orders from the records system wait for a nurse.\nALTER TABLE med_orders ADD COLUMN status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','pending_review','stopped'));\nALTER TABLE med_orders ADD COLUMN starts_on date;\nALTER TABLE med_orders ADD COLUMN ends_on date;\nALTER TABLE med_orders ADD COLUMN external_id text;\nDROP POLICY see_meds ON med_orders;\nCREATE POLICY see_meds ON med_orders FOR SELECT USING (kp_can_view(patient_id, 'meds') AND (status <> 'pending_review' OR kp_is_clinician()));\n\nALTER TABLE integration_keys ENABLE ROW LEVEL SECURITY;\nALTER TABLE record_imports ENABLE ROW LEVEL SECURITY;\nALTER TABLE record_items ENABLE ROW LEVEL SECURITY;\n\n-- Admins manage keys (they never see the key itself after it's created).\nCREATE POLICY admin_keys ON integration_keys FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin');\n-- The import log holds counts only: admins and clinicians may read it.\nCREATE POLICY read_imports ON record_imports FOR SELECT USING (clinic_id = kp_clinic() AND (kp_role() = 'clinic_admin' OR kp_is_clinician()));\n-- The records themselves are clinical: nurses and physicians only.\nCREATE POLICY clinician_items ON record_items FOR SELECT USING (clinic_id = kp_clinic() AND kp_is_clinician());\nCREATE POLICY clinician_review ON record_items FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\n\n-- Key creation and the importer run as the database owner (server side), never as kp_app.\nREVOKE ALL ON integration_keys FROM kp_app;\nGRANT SELECT (id, clinic_id, name, key_hint, created_by, created_at, last_used_at, revoked_at) ON integration_keys TO kp_app;\nGRANT SELECT ON record_imports TO kp_app;\nGRANT SELECT, UPDATE (status, reason, patient_id, reviewed_by_name, reviewed_at, updated_at, lab_result_id, med_order_id) ON record_items TO kp_app;\nGRANT UPDATE (status) ON med_orders TO kp_app;\nCREATE POLICY clinician_meds ON med_orders FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_clinician()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\nGRANT INSERT ON dose_logs TO kp_app;\nCREATE POLICY clinician_add_doses ON dose_logs FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\n-- A nurse can add a confirmed order for a record that arrived without a patient match.\nGRANT INSERT ON med_orders TO kp_app;\nCREATE POLICY clinician_add_meds ON med_orders FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_clinician());\n" },
  { name: "013_patients_appointments_sources.sql", sql: "-- Patients added by staff, appointments, HL7 v2 and uploaded files, and pulling from a records\n-- system's FHIR API (SMART Backend Services).\n\n-- ---------- appointments ----------\nCREATE TABLE appointments (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  starts_at timestamptz NOT NULL,\n  kind text NOT NULL CHECK (kind IN ('monitoring','blood_test','consult','retrieval','transfer','procedure','other')),\n  -- What the patient sees, e.g. \"Monitoring visit: ultrasound and blood work\".\n  title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120),\n  location text CHECK (char_length(location) <= 160),\n  status text NOT NULL DEFAULT 'booked' CHECK (status IN ('booked','cancelled')),\n  source text NOT NULL DEFAULT 'staff' CHECK (source IN ('staff','records')),\n  external_id text,\n  created_by_name text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX appointments_external ON appointments (clinic_id, external_id) WHERE external_id IS NOT NULL;\nALTER TABLE appointments ENABLE ROW LEVEL SECURITY;\n-- The patient, support people she shares her schedule with, and staff who see schedules.\nCREATE POLICY see_appointments ON appointments FOR SELECT USING (clinic_id = kp_clinic() AND kp_can_view(patient_id, 'schedule'));\nCREATE POLICY staff_book ON appointments FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_role() IN ('nurse','physician','scheduler') AND kp_can_view(patient_id, 'schedule'));\nCREATE POLICY staff_change ON appointments FOR UPDATE USING (clinic_id = kp_clinic() AND kp_role() IN ('nurse','physician','scheduler')) WITH CHECK (clinic_id = kp_clinic() AND kp_role() IN ('nurse','physician','scheduler'));\nGRANT SELECT, INSERT, UPDATE ON appointments TO kp_app;\n\n-- ---------- patients added by staff ----------\nALTER TABLE patients ADD COLUMN added_by_name text;\n-- Who can see the patient list to add or edit: nurses, physicians, schedulers (already covered by\n-- see_patient via kp_can_view 'schedule'). Writes go through server code as the owner, after a role check.\n\n-- ---------- records: more kinds and formats ----------\nALTER TABLE record_items DROP CONSTRAINT record_items_kind_check;\nALTER TABLE record_items ADD CONSTRAINT record_items_kind_check CHECK (kind IN ('result','hcg','med_order','med_stop','appointment'));\nALTER TABLE record_imports DROP CONSTRAINT record_imports_format_check;\nALTER TABLE record_imports ADD CONSTRAINT record_imports_format_check CHECK (format IN ('fhir','csv','sample','hl7','upload','pull'));\nALTER TABLE record_imports ADD COLUMN uploaded_by_name text;\n\n-- ---------- pulling from the records system's FHIR API ----------\n-- Pumpkin makes its own key pair per clinic. The public half is published as a JWK Set for the\n-- records system; the private half is stored encrypted with the server's secret (KINPATH_SECRET_KEY).\nCREATE TABLE fhir_sources (\n  clinic_id text PRIMARY KEY REFERENCES clinics(id),\n  base_url text,\n  token_url text,\n  client_id text,\n  scope text NOT NULL DEFAULT 'system/Patient.rs system/Observation.rs system/MedicationRequest.rs system/Appointment.rs',\n  mrn_system text,\n  kid text NOT NULL,\n  public_jwk jsonb NOT NULL,\n  private_key_enc text NOT NULL,\n  enabled boolean NOT NULL DEFAULT false,\n  last_pulled_at timestamptz,\n  last_status text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE fhir_sources ENABLE ROW LEVEL SECURITY;\nCREATE POLICY admin_sources ON fhir_sources FOR SELECT USING (clinic_id = kp_clinic() AND kp_role() = 'clinic_admin');\nREVOKE ALL ON fhir_sources FROM kp_app;\nGRANT SELECT (clinic_id, base_url, token_url, client_id, scope, mrn_system, kid, public_jwk, enabled, last_pulled_at, last_status, created_at, updated_at) ON fhir_sources TO kp_app;\n\n-- Patients' ids in the records system's FHIR API, learned by searching on MRN.\nCREATE TABLE fhir_patient_links (\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  fhir_id text NOT NULL,\n  PRIMARY KEY (clinic_id, patient_id)\n);\nALTER TABLE fhir_patient_links ENABLE ROW LEVEL SECURITY;\nREVOKE ALL ON fhir_patient_links FROM kp_app;\n" },
  { name: "014_money.sql", sql: "-- Money: cost estimates, insurance and benefits, charges and payments, financing options, and\n-- questions about costs. Everything patient-specific sits in the 'money' section:\n--   the patient sees her own; financial counselors see every patient's at their clinic;\n--   a support person only if she shares 'money' (off by default); nurses, physicians, schedulers\n--   and admins don't see it.\n-- Amounts are whole cents. Pumpkin doesn't take payments yet (see docs/PAYMENTS.md).\n\nCREATE FUNCTION kp_is_counselor() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT kp_role() = 'financial_counselor' $$;\n\n-- ---------- estimates ----------\nCREATE TABLE finance_estimates (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120),\n  note text CHECK (char_length(note) <= 1000),          -- what she reads with it\n  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','shared','replaced')),\n  valid_until date,\n  source text NOT NULL DEFAULT 'staff' CHECK (source IN ('staff','records')),\n  external_id text,\n  created_by_name text,\n  shared_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX finance_estimates_external ON finance_estimates (clinic_id, external_id) WHERE external_id IS NOT NULL;\n\nCREATE TABLE finance_estimate_items (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  estimate_id uuid NOT NULL REFERENCES finance_estimates(id) ON DELETE CASCADE,\n  label text NOT NULL CHECK (char_length(label) BETWEEN 1 AND 120),\n  category text NOT NULL DEFAULT 'other' CHECK (category IN ('clinic','medications','lab','anesthesia','storage','other')),\n  amount_cents bigint NOT NULL CHECK (amount_cents >= 0),\n  insurance_cents bigint NOT NULL DEFAULT 0 CHECK (insurance_cents >= 0 AND insurance_cents <= amount_cents),\n  sort_order int NOT NULL DEFAULT 0\n);\n\n-- ---------- coverage ----------\nCREATE TABLE finance_coverage (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL DEFAULT 'insurance' CHECK (kind IN ('insurance','employer_benefit','self_pay')),\n  payer_name text CHECK (char_length(payer_name) <= 120),\n  plan_name text CHECK (char_length(plan_name) <= 120),\n  member_last4 text CHECK (member_last4 ~ '^[A-Za-z0-9]{1,4}$'),   -- never the full member id\n  fertility_benefit text CHECK (char_length(fertility_benefit) <= 500),\n  lifetime_max_cents bigint, lifetime_used_cents bigint NOT NULL DEFAULT 0,\n  cycles_max int, cycles_used int NOT NULL DEFAULT 0,\n  deductible_cents bigint, deductible_met_cents bigint NOT NULL DEFAULT 0,\n  oop_max_cents bigint, oop_met_cents bigint NOT NULL DEFAULT 0,\n  prior_auth text NOT NULL DEFAULT 'none' CHECK (prior_auth IN ('none','needed','submitted','approved','denied')),\n  ends_on date,\n  active boolean NOT NULL DEFAULT true,\n  source text NOT NULL DEFAULT 'staff' CHECK (source IN ('staff','records')),\n  external_id text,\n  updated_by_name text,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX finance_coverage_external ON finance_coverage (clinic_id, external_id) WHERE external_id IS NOT NULL;\n\n-- ---------- charges and payments ----------\nCREATE TABLE finance_ledger (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('charge','payment','adjustment','refund')),\n  description text NOT NULL CHECK (char_length(description) BETWEEN 1 AND 160),\n  amount_cents bigint NOT NULL CHECK (amount_cents > 0),\n  occurred_on date NOT NULL,\n  due_on date,\n  method text CHECK (method IN ('card','check','cash','bank','financing','insurance','other')),\n  receipt_number text,\n  voided_at timestamptz,\n  source text NOT NULL DEFAULT 'staff' CHECK (source IN ('staff','records')),\n  external_id text,\n  created_by_name text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  CHECK (due_on IS NULL OR kind = 'charge')\n);\nCREATE UNIQUE INDEX finance_ledger_external ON finance_ledger (clinic_id, external_id) WHERE external_id IS NOT NULL;\n\n-- ---------- financing options (clinic-wide, not patient data) ----------\nCREATE TABLE finance_partners (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  kind text NOT NULL CHECK (kind IN ('loan','grant','discount','employer','other')),\n  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),\n  description text NOT NULL CHECK (char_length(description) BETWEEN 1 AND 400),\n  url text CHECK (url ~ '^https://'),\n  phone text CHECK (char_length(phone) <= 30),\n  sort_order int NOT NULL DEFAULT 0,\n  active boolean NOT NULL DEFAULT true,\n  updated_by_name text,\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ---------- questions about costs (to the financial counselor, not the nurses) ----------\nCREATE TABLE finance_questions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  estimate_id uuid REFERENCES finance_estimates(id),\n  question text NOT NULL CHECK (char_length(question) BETWEEN 1 AND 1000),\n  answer text CHECK (char_length(answer) <= 2000),\n  answered_by_name text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  answered_at timestamptz,\n  read_at timestamptz\n);\n\n-- ---------- access ----------\nALTER TABLE finance_estimates ENABLE ROW LEVEL SECURITY;\nALTER TABLE finance_estimate_items ENABLE ROW LEVEL SECURITY;\nALTER TABLE finance_coverage ENABLE ROW LEVEL SECURITY;\nALTER TABLE finance_ledger ENABLE ROW LEVEL SECURITY;\nALTER TABLE finance_partners ENABLE ROW LEVEL SECURITY;\nALTER TABLE finance_questions ENABLE ROW LEVEL SECURITY;\n\n-- Patients and support people see estimates only once shared; counselors see drafts too.\nCREATE POLICY see_estimates ON finance_estimates FOR SELECT USING (clinic_id = kp_clinic() AND kp_can_view(patient_id, 'money') AND (status <> 'draft' OR kp_is_counselor()));\nCREATE POLICY counselor_estimates ON finance_estimates FOR ALL USING (clinic_id = kp_clinic() AND kp_is_counselor()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_counselor());\nCREATE POLICY see_estimate_items ON finance_estimate_items FOR SELECT USING (clinic_id = kp_clinic() AND EXISTS (SELECT 1 FROM finance_estimates e WHERE e.id = estimate_id));\nCREATE POLICY counselor_estimate_items ON finance_estimate_items FOR ALL USING (clinic_id = kp_clinic() AND kp_is_counselor()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_counselor());\n\nCREATE POLICY see_coverage ON finance_coverage FOR SELECT USING (clinic_id = kp_clinic() AND kp_can_view(patient_id, 'money'));\nCREATE POLICY counselor_coverage ON finance_coverage FOR ALL USING (clinic_id = kp_clinic() AND kp_is_counselor()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_counselor());\n\nCREATE POLICY see_ledger ON finance_ledger FOR SELECT USING (clinic_id = kp_clinic() AND kp_can_view(patient_id, 'money'));\nCREATE POLICY counselor_ledger ON finance_ledger FOR ALL USING (clinic_id = kp_clinic() AND kp_is_counselor()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_counselor());\n\nCREATE POLICY see_partners ON finance_partners FOR SELECT USING (clinic_id = kp_clinic());\nCREATE POLICY manage_partners ON finance_partners FOR ALL USING (clinic_id = kp_clinic() AND kp_role() IN ('financial_counselor','clinic_admin')) WITH CHECK (clinic_id = kp_clinic() AND kp_role() IN ('financial_counselor','clinic_admin'));\n\n-- Questions are between the patient and the counselor; support people don't see them.\nCREATE POLICY see_questions ON finance_questions FOR SELECT USING (clinic_id = kp_clinic() AND (kp_is_patient_self(patient_id) OR kp_is_counselor()));\nCREATE POLICY patient_asks ON finance_questions FOR INSERT WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND answer IS NULL);\nCREATE POLICY counselor_answers ON finance_questions FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_counselor()) WITH CHECK (clinic_id = kp_clinic() AND kp_is_counselor());\nCREATE POLICY patient_reads_answer ON finance_questions FOR UPDATE USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id) AND answer IS NOT NULL) WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\n-- A patient may only mark an answer read; everything else is locked to her.\nCREATE FUNCTION kp_question_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF kp_role() = 'patient' AND (NEW.question IS DISTINCT FROM OLD.question OR NEW.answer IS DISTINCT FROM OLD.answer\n     OR NEW.answered_by_name IS DISTINCT FROM OLD.answered_by_name OR NEW.answered_at IS DISTINCT FROM OLD.answered_at OR NEW.patient_id IS DISTINCT FROM OLD.patient_id) THEN\n    RAISE EXCEPTION 'patients can only mark an answer as read';\n  END IF;\n  RETURN NEW;\nEND $$;\nCREATE TRIGGER finance_question_guard BEFORE UPDATE ON finance_questions FOR EACH ROW EXECUTE FUNCTION kp_question_guard();\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON finance_estimates, finance_estimate_items, finance_coverage, finance_ledger, finance_partners TO kp_app;\nGRANT SELECT, INSERT, UPDATE ON finance_questions TO kp_app;\n\n-- Financial counselors review billing records the records connection couldn't match.\nALTER TABLE record_items DROP CONSTRAINT record_items_kind_check;\nALTER TABLE record_items ADD CONSTRAINT record_items_kind_check CHECK (kind IN ('result','hcg','med_order','med_stop','appointment','coverage','ledger','estimate'));\nDROP POLICY clinician_items ON record_items;\nDROP POLICY clinician_review ON record_items;\nCREATE POLICY reviewer_items ON record_items FOR SELECT USING (clinic_id = kp_clinic() AND (\n  (kp_is_clinician() AND kind NOT IN ('coverage','ledger','estimate')) OR (kp_is_counselor() AND kind IN ('coverage','ledger','estimate'))));\nCREATE POLICY reviewer_update ON record_items FOR UPDATE\n  USING (clinic_id = kp_clinic() AND ((kp_is_clinician() AND kind NOT IN ('coverage','ledger','estimate')) OR (kp_is_counselor() AND kind IN ('coverage','ledger','estimate'))))\n  WITH CHECK (clinic_id = kp_clinic() AND ((kp_is_clinician() AND kind NOT IN ('coverage','ledger','estimate')) OR (kp_is_counselor() AND kind IN ('coverage','ledger','estimate'))));\n\n-- Reading billing from the records system's FHIR API needs two more read scopes.\nALTER TABLE fhir_sources ALTER COLUMN scope SET DEFAULT 'system/Patient.rs system/Observation.rs system/MedicationRequest.rs system/Appointment.rs system/Coverage.rs system/Invoice.rs';\n" },
  { name: "015_on_your_own.sql", sql: "-- Patients on their own: Pumpkin before (or without) a clinic.\n--\n-- Each person who signs up on her own gets a private space: a row in clinics with kind 'personal'.\n-- That keeps every existing wall (row-level security by clinic) exactly as it is: nobody else is\n-- in her space, there are no staff, and her support people see only what she shares.\n-- In a personal space (and only there) the patient may add and change her own meds, results,\n-- appointments and costs. In a clinic's space those still come from the clinic.\n\nALTER TABLE clinics ADD COLUMN kind text NOT NULL DEFAULT 'clinic' CHECK (kind IN ('clinic','personal','system'));\n-- Messages sent before anyone has an account (waitlist notes, sign-up codes) belong to Pumpkin itself.\nINSERT INTO clinics (id, name, kind) VALUES ('pumpkin', 'Pumpkin', 'system') ON CONFLICT (id) DO NOTHING;\n\nCREATE FUNCTION kp_is_personal() RETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT EXISTS (SELECT 1 FROM clinics WHERE id = kp_clinic() AND kind = 'personal')\n$$;\n-- The signed-in patient, in her own personal space, acting on her own record.\nCREATE FUNCTION kp_owns(p_patient uuid) RETURNS boolean\nLANGUAGE sql STABLE AS $$ SELECT kp_is_personal() AND kp_is_patient_self(p_patient) $$;\n\n-- ---------- waitlist and early access (the sign-up service only; the app role can't read it) ----------\nCREATE TABLE early_access (\n  identifier text PRIMARY KEY,               -- email (lowercase) or phone (digits), like sign-in\n  status text NOT NULL DEFAULT 'waiting' CHECK (status IN ('waiting','invited','joined')),\n  source text NOT NULL DEFAULT 'app' CHECK (source IN ('app','site','import')),\n  added_at timestamptz NOT NULL DEFAULT now(),\n  invited_at timestamptz,\n  joined_at timestamptz\n);\nCREATE TABLE signup_codes (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  identifier text NOT NULL,\n  code_hash text NOT NULL,\n  attempts int NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  expires_at timestamptz NOT NULL,\n  used_at timestamptz,\n  -- After the code checks out, a short-lived ticket lets her finish setting up (hash only).\n  ticket_hash text UNIQUE\n);\n\n-- \"Ask my clinic to join\": the clinic's name, so Pumpkin can reach out. No health details.\nCREATE TABLE clinic_requests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_name text NOT NULL CHECK (char_length(clinic_name) BETWEEN 2 AND 120),\n  -- Kept so she can be told when her clinic joins; removed if she deletes her account.\n  patient_id uuid,\n  source text NOT NULL DEFAULT 'app' CHECK (source IN ('app','site')),\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- ---------- her profile in a personal space ----------\nCREATE TABLE personal_profiles (\n  patient_id uuid PRIMARY KEY REFERENCES patients(id),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  stage text NOT NULL CHECK (stage IN ('just_starting','in_cycle','two_week_wait','after_hard_result','freezing_eggs','between_cycles')),\n  clinic_name text CHECK (char_length(clinic_name) <= 120),\n  -- Her clinic's after-hours line. Without a clinic on Pumpkin, urgent symptoms go here (or 911).\n  after_hours_phone text CHECK (char_length(after_hours_phone) <= 30),\n  asked_clinic_at timestamptz,\n  -- Calendar feed: only the hash of the secret link is kept.\n  calendar_token_hash text UNIQUE,\n  -- Calendar titles say only \"Appointment\" unless she turns detail on (calendars are often shared).\n  calendar_detail boolean NOT NULL DEFAULT false,\n  -- Forwarding address token (add+<token>@...). It can only add items she must confirm.\n  inbox_token text UNIQUE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE personal_profiles ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_profile ON personal_profiles FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id));\nGRANT SELECT, INSERT, UPDATE ON personal_profiles TO kp_app;\n\n-- ---------- \"Add anything\": what she sends, and what Pumpkin read from it ----------\nCREATE TABLE captures (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('photo','pdf','text','voice','email','sample')),\n  filename text CHECK (char_length(filename) <= 200),\n  mime text CHECK (char_length(mime) <= 100),\n  bytes bytea,\n  text_input text CHECK (char_length(text_input) <= 20000),\n  status text NOT NULL DEFAULT 'reading' CHECK (status IN ('reading','ready','failed','urgent')),\n  problem text,\n  engine text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  CHECK (bytes IS NULL OR octet_length(bytes) <= 12000000)\n);\nCREATE TABLE capture_items (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  capture_id uuid NOT NULL REFERENCES captures(id) ON DELETE CASCADE,\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  kind text NOT NULL CHECK (kind IN ('medication','result','appointment','cost','question')),\n  data jsonb NOT NULL,\n  unsure text[] NOT NULL DEFAULT '{}',   -- fields Pumpkin wasn't sure it read right\n  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','saved','dismissed')),\n  saved_ref uuid,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  decided_at timestamptz\n);\nALTER TABLE captures ENABLE ROW LEVEL SECURITY;\nALTER TABLE capture_items ENABLE ROW LEVEL SECURITY;\n-- Only her. Never support people, never anyone else.\nCREATE POLICY own_captures ON captures FOR ALL USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nCREATE POLICY own_capture_items ON capture_items FOR ALL USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT, UPDATE, DELETE ON captures, capture_items TO kp_app;\n\n-- ---------- questions for her next visit ----------\nCREATE TABLE visit_questions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  clinic_id text NOT NULL REFERENCES clinics(id),\n  patient_id uuid NOT NULL REFERENCES patients(id),\n  question text NOT NULL CHECK (char_length(question) BETWEEN 1 AND 500),\n  asked_at timestamptz,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\nALTER TABLE visit_questions ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_questions ON visit_questions FOR ALL USING (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_is_patient_self(patient_id));\nGRANT SELECT, INSERT, UPDATE, DELETE ON visit_questions TO kp_app;\n\n-- ---------- what she enters herself, in her own space ----------\nALTER TABLE med_orders ADD COLUMN source text NOT NULL DEFAULT 'clinic' CHECK (source IN ('clinic','patient'));\nALTER TABLE med_orders ADD COLUMN instructions text CHECK (char_length(instructions) <= 500);\nALTER TABLE med_orders ADD COLUMN capture_id uuid REFERENCES captures(id) ON DELETE SET NULL;\n\nALTER TABLE lab_results ALTER COLUMN stim_day DROP NOT NULL;\n-- The lab's own reference range, exactly as printed on her report. Never Pumpkin's judgment.\nALTER TABLE lab_results ADD COLUMN ref_low numeric;\nALTER TABLE lab_results ADD COLUMN ref_high numeric;\nALTER TABLE lab_results ADD COLUMN ref_text text CHECK (char_length(ref_text) <= 80);\nALTER TABLE lab_results ADD COLUMN test_name text CHECK (char_length(test_name) <= 80);\nALTER TABLE lab_results ADD COLUMN capture_id uuid REFERENCES captures(id) ON DELETE SET NULL;\n\nALTER TABLE appointments DROP CONSTRAINT appointments_source_check;\nALTER TABLE appointments ADD CONSTRAINT appointments_source_check CHECK (source IN ('staff','records','patient'));\nALTER TABLE finance_ledger DROP CONSTRAINT finance_ledger_source_check;\nALTER TABLE finance_ledger ADD CONSTRAINT finance_ledger_source_check CHECK (source IN ('staff','records','patient'));\nALTER TABLE finance_ledger ADD COLUMN capture_id uuid REFERENCES captures(id) ON DELETE SET NULL;\n\nCREATE POLICY solo_cycles ON cycles FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id));\nCREATE POLICY solo_meds ON med_orders FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id) AND source = 'patient');\nCREATE POLICY solo_doses ON dose_logs FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id));\nCREATE POLICY solo_results ON lab_results FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id) AND source = 'patient_upload' AND entered_by = kp_user());\nCREATE POLICY solo_appointments ON appointments FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id) AND source = 'patient');\nCREATE POLICY solo_ledger ON finance_ledger FOR ALL USING (clinic_id = kp_clinic() AND kp_owns(patient_id)) WITH CHECK (clinic_id = kp_clinic() AND kp_owns(patient_id) AND source = 'patient');\nGRANT SELECT, INSERT, UPDATE ON cycles TO kp_app;\nGRANT UPDATE, DELETE ON med_orders TO kp_app;\nGRANT DELETE ON dose_logs, lab_results, appointments TO kp_app;\nGRANT UPDATE ON lab_results TO kp_app;\n" },
];
